        }
        if (paymentRequest == null) {
            throw new Xtj87Exception("결제 정보가 없습니다.");
        }
    }




    private Xzz58 getSaleBidAndValidate(Long saleBidId) {
        Xzz58 saleBid = saleBidQueryService.findById(saleBidId);
