            throw new Xkt44Exception("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
        }

        Xgg74 sale = saleBid.getSale();
        if (sale == null) {
            throw new Xnb95Exception("판매 입찰과 연결된 판매 정보가 없습니다.");
        }

        return saleBid;
    }




    private Xzj27 createInstantOrderBid(Xdg64 order, Xzz58 saleBid, Xgg74 sale) {
        Xdh20 productSize = saleBid.getProductSize();

        Xzj27 orderBid = Xzj27.builder()
                .user(order.getUser())
                .productSize(productSize)
                .bidPrice(saleBid.getBidPrice())
                .status(Xtz73Status.MATCHED)
                .order(order)
                .sale(sale)
                .build();


        orderBid.assignOrder(order);


        orderBid.markAsInstantPurchase();
        return orderBidRepository.save(orderBid);
    }




    private void handleOrderBidCreationException(Exception e, String operation) {
        if (e instanceof Xdg64Exception) {
            throw (Xdg64Exception) e;
        }
        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
        throw new Xst47Exception(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
    }








